#!/usr/bin/env python3\n\"\"\"Main script to scrape medical documents and generate QA pairs.\"\"\"\n\nimport logging\nfrom pathlib import Path\nimport sys\n\n# Add src to path\nsys.path.insert(0, str(Path(__file__).parent.parent))\n\nfrom src.data_preparation.web_scraper import WikipediaScraper, MedicalWebsiteScraper\nfrom src.data_preparation.data_loader import DataLoader\nfrom src.data_preparation.qa_generator import SimpleQAGenerator\n\n# Setup logging\nlogging.basicConfig(\n    level=logging.INFO,\n    format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',\n    handlers=[\n        logging.FileHandler('data_collection.log'),\n        logging.StreamHandler()\n    ]\n)\nlogger = logging.getLogger(__name__)\n\n\n# Vietnamese Wikipedia medical topics\nMEDICAL_TOPICS = [\n    \"Cảm_lạnh\",\n    \"Bệnh_cúm\",\n    \"Viêm_phổi\",\n    \"Tiêu_chảy\",\n    \"Cao_huyết_áp\",\n    \"Đái_tháo_đường\",\n    \"Sốc_(chẩn_đoán_y_tế)\",\n    \"Chấn_thương_sọ_não\",\n    \"Tăng_cân\",\n    \"Béo_phì\",\n    \"Thiếu_máu\",\n    \"Cholera\",\n    \"Lao_(bệnh)\",\n    \"Quai_bị\",\n    \"Sởi\",\n    \"Rubella\",\n    \"Thủy_đậu\",\n    \"Viêm_gan_B\",\n    \"HIV/AIDS\",\n    \"Bỏng\",\n    \"Dị_ứng\",\n    \"Hen_suyễn\",\n    \"Mụn_trứng_cá\",\n    \"Viêm_da_tiếp_xúc\",\n    \"Huyết_áp_thấp\",\n    \"Tim_đập_nhanh\",\n    \"Đau_tức_ngực\",\n    \"Chứng_mất_ngủ\",\n    \"Trầm_cảm\",\n    \"Rối_loạn_lo_âu\",\n]\n\n\ndef scrape_wikipedia_articles():\n    \"\"\"Scrape medical articles from Wikipedia.\"\"\"\n    logger.info(\"=\" * 80)\n    logger.info(\"Starting Wikipedia scraping\")\n    logger.info(\"=\" * 80)\n    \n    scraper = WikipediaScraper(output_dir=\"data/raw/documents/\")\n    articles = scraper.scrape_medical_topics(MEDICAL_TOPICS)\n    \n    logger.info(f\"Successfully scraped {len(articles)} articles\")\n    return articles\n\n\ndef load_documents():\n    \"\"\"Load all documents from data/raw/documents/.\"\"\"\n    logger.info(\"=\" * 80)\n    logger.info(\"Loading documents\")\n    logger.info(\"=\" * 80)\n    \n    loader = DataLoader(\"data/raw/documents/\")\n    documents = loader.load_txt_files()\n    \n    logger.info(f\"Loaded {len(documents)} documents\")\n    return documents\n\n\ndef extract_document_info(documents):\n    \"\"\"Extract title and content from documents.\"\"\"\n    extracted = []\n    \n    for doc in documents:\n        content = doc['content']\n        lines = content.split('\\n')\n        \n        # First line is usually the title\n        title = lines[0] if lines else doc['filename']\n        if title.startswith('Title:'):\n            title = title.replace('Title:', '').strip()\n        \n        extracted.append({\n            'title': title,\n            'content': '\\n'.join(lines[3:]),  # Skip metadata lines\n            'filename': doc['filename']\n        })\n    \n    return extracted\n\n\ndef generate_qa_pairs(documents):\n    \"\"\"Generate QA pairs from documents.\"\"\"\n    logger.info(\"=\" * 80)\n    logger.info(\"Generating QA pairs\")\n    logger.info(\"=\" * 80)\n    \n    generator = SimpleQAGenerator()\n    qa_pairs = generator.generate_qa_pairs(documents)\n    \n    logger.info(f\"Generated {len(qa_pairs)} QA pairs\")\n    \n    # Save to file\n    output_file = \"data/processed/qa_pairs_generated.jsonl\"\n    generator.save_qa_pairs(qa_pairs, output_file)\n    logger.info(f\"Saved QA pairs to {output_file}\")\n    \n    return qa_pairs\n\n\ndef print_statistics(documents, qa_pairs):\n    \"\"\"Print statistics about scraped data.\"\"\"\n    logger.info(\"=\" * 80)\n    logger.info(\"Data Collection Statistics\")\n    logger.info(\"=\" * 80)\n    \n    total_text = sum(len(doc.get('content', '')) for doc in documents)\n    \n    logger.info(f\"Total documents: {len(documents)}\")\n    logger.info(f\"Total text length: {total_text:,} characters\")\n    logger.info(f\"Average document size: {total_text // max(len(documents), 1):,} characters\")\n    logger.info(f\"\\nTotal QA pairs generated: {len(qa_pairs)}\")\n    \n    # Category distribution\n    categories = {}\n    for qa in qa_pairs:\n        cat = qa.get('category', 'unknown')\n        categories[cat] = categories.get(cat, 0) + 1\n    \n    logger.info(\"\\nQA pairs by category:\")\n    for cat, count in sorted(categories.items(), key=lambda x: x[1], reverse=True):\n        logger.info(f\"  {cat}: {count}\")\n    \n    logger.info(\"\\n\" + \"=\" * 80)\n    logger.info(\"Next steps:\")\n    logger.info(\"1. Review generated QA pairs in data/processed/qa_pairs_generated.jsonl\")\n    logger.info(\"2. Manually add/correct QA pairs as needed\")\n    logger.info(\"3. Ensure at least 300 QA pairs for fine-tuning\")\n    logger.info(\"4. Create test set with 50+ QA pairs\")\n    logger.info(\"=\" * 80)\n\n\ndef main():\n    \"\"\"Main execution function.\"\"\"\n    try:\n        # Step 1: Scrape Wikipedia\n        logger.info(\"\\n\" + \"#\" * 80)\n        logger.info(\"STEP 1: Web Scraping\")\n        logger.info(\"#\" * 80 + \"\\n\")\n        scrape_wikipedia_articles()\n        \n        # Step 2: Load documents\n        logger.info(\"\\n\" + \"#\" * 80)\n        logger.info(\"STEP 2: Loading Documents\")\n        logger.info(\"#\" * 80 + \"\\n\")\n        documents = load_documents()\n        \n        # Step 3: Extract document info\n        logger.info(\"\\n\" + \"#\" * 80)\n        logger.info(\"STEP 3: Extracting Document Information\")\n        logger.info(\"#\" * 80 + \"\\n\")\n        extracted_docs = extract_document_info(documents)\n        logger.info(f\"Extracted information from {len(extracted_docs)} documents\")\n        \n        # Step 4: Generate QA pairs\n        logger.info(\"\\n\" + \"#\" * 80)\n        logger.info(\"STEP 4: Generating QA Pairs\")\n        logger.info(\"#\" * 80 + \"\\n\")\n        qa_pairs = generate_qa_pairs(extracted_docs)\n        \n        # Step 5: Print statistics\n        print_statistics(extracted_docs, qa_pairs)\n        \n        logger.info(\"\\n✅ Data collection completed successfully!\")\n        \n    except Exception as e:\n        logger.error(f\"Error during data collection: {e}\", exc_info=True)\n        sys.exit(1)\n\n\nif __name__ == \"__main__\":\n    main()\n"